package localchat;
import javax.swing.*;import javax.swing.filechooser.FileNameExtensionFilter;import java.awt.*;import java.awt.event.*;import java.nio.file.*;import java.util.*;import java.util.List;

/** Explicit preview/activate for all four factories, including a missing initial catalogue. */
final class CatalogueDialog extends JDialog {
 final JComboBox<String> factory=new JComboBox<>(new String[]{I18n.text("Fabrica neconfirmata"),"Soest","Alphen","Veenoord","Lelystad"});
 final JTextField source=new JTextField();final JButton choose=new JButton("\u2026"),compare=new JButton(I18n.text("Compara lista")),apply=new JButton(I18n.text("Importa si activeaza")),folder=new JButton(I18n.text("Deschide arhiva"));
 final JCheckBox confirmed=new JCheckBox(I18n.text("Confirm ca fisierul apartine fabricii selectate.")),complete=new JCheckBox(I18n.text("Lista este completa; confirm codurile absente afisate."));
 final JTextArea details=new JTextArea(14,65);final JLabel current=new JLabel(" "),status=new JLabel(I18n.text("Alege fabrica si lista XLSX noua."));final JProgressBar progress=new JProgressBar();
 final CatalogueStore store;CatalogueStore.Preview preview;boolean running;private int infoGeneration;
 CatalogueDialog(JFrame owner,CatalogueStore store){
  super(owner,I18n.text("Cataloage fabrici"),false);this.store=store;setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
  source.setEditable(false);details.setEditable(false);details.setLineWrap(true);details.setWrapStyleWord(true);details.setFont(UIManager.getFont("Label.font"));
  JPanel form=new JPanel(new BorderLayout(8,8));JPanel top=new JPanel(new BorderLayout(8,8));top.add(new JLabel(I18n.text("Fabrica")),BorderLayout.WEST);top.add(factory);form.add(top,BorderLayout.NORTH);
  JPanel path=new JPanel(new BorderLayout(6,6));path.add(source);path.add(choose,BorderLayout.EAST);path.setBorder(BorderFactory.createTitledBorder(I18n.text("Lista XLSX")));form.add(path);form.add(current,BorderLayout.SOUTH);
  JScrollPane scroll=new JScrollPane(details);scroll.putClientProperty("FlatLaf.style","arc: 14");
  JPanel confirmations=new JPanel(new GridLayout(0,1,2,2));confirmations.add(confirmed);confirmations.add(complete);complete.setVisible(false);
  JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));buttons.add(folder);buttons.add(compare);buttons.add(apply);
  JPanel lower=new JPanel(new BorderLayout(4,6));lower.add(confirmations,BorderLayout.NORTH);JPanel state=new JPanel(new BorderLayout(4,4));state.add(status,BorderLayout.NORTH);state.add(progress);state.add(buttons,BorderLayout.SOUTH);lower.add(state);
  JPanel panel=new JPanel(new BorderLayout(8,8));panel.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));panel.add(form,BorderLayout.NORTH);panel.add(scroll);panel.add(lower,BorderLayout.SOUTH);setContentPane(panel);
  choose.addActionListener(e->{JFileChooser picker=new JFileChooser(Path.of(System.getProperty("user.home"),"Downloads").toFile());picker.setFileFilter(new FileNameExtensionFilter("XLSX","xlsx"));if(picker.showOpenDialog(this)==JFileChooser.APPROVE_OPTION){source.setText(picker.getSelectedFile().getAbsolutePath());invalidatePreview();}});
  factory.addActionListener(e->{invalidatePreview();loadInfo();});confirmed.addActionListener(e->controls());complete.addActionListener(e->controls());compare.addActionListener(e->compare());apply.addActionListener(e->activate());
  folder.addActionListener(e->{try{Path archivePath=store.app.resolve("pdfcontrol/data_lokaal/catalogue_sources").resolve(selected());if(!Files.isDirectory(archivePath))archivePath=store.app.resolve("pdfcontrol/data_lokaal");if(Files.isDirectory(archivePath))Desktop.getDesktop().open(archivePath.toFile());}catch(Exception error){status.setText(error.getMessage());}});
  addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){if(!running)dispose();else status.setText(I18n.text("Operatie locala in curs; asteapta terminarea."));}});
  controls();setMinimumSize(new Dimension(660,470));setSize(780,560);setLocationRelativeTo(owner);
 }
 String selected(){return factory.getSelectedIndex()>0?factory.getSelectedItem().toString().toLowerCase(Locale.ROOT):"";}
 void invalidatePreview(){preview=null;confirmed.setSelected(false);complete.setSelected(false);complete.setVisible(false);details.setText("");controls();}
 void controls(){factory.setEnabled(!running);choose.setEnabled(!running);compare.setEnabled(!running&&!selected().isEmpty()&&!source.getText().isBlank());confirmed.setEnabled(!running);complete.setEnabled(!running);apply.setEnabled(!running&&!store.readOnly&&preview!=null&&confirmed.isSelected()&&(!complete.isVisible()||complete.isSelected()));}
 void loadInfo(){String selected=selected();int generation=++infoGeneration;if(selected.isEmpty()){current.setText(" ");return;}new SwingWorker<Map<String,Object>,Void>(){protected Map<String,Object> doInBackground()throws Exception{return store.info(selected);}protected void done(){if(generation!=infoGeneration)return;try{Object data=get();current.setText(Boolean.TRUE.equals(Json.get(data,"exists"))?I18n.text("Catalog activ: {0} articole; actualizat: {1}",CatalogueStore.number(data,"records"),date(Json.get(data,"verified_at"))):I18n.text("Niciun catalog importat. Poti importa prima lista."));current.setToolTipText(Objects.toString(Json.get(data,"source"),""));}catch(Exception error){current.setText(I18n.text("Catalog invalid."));}}}.execute();}
 void compare(){if(running||selected().isEmpty()||source.getText().isBlank())return;String selected=selected();Path file=Path.of(source.getText());preview=null;confirmed.setSelected(false);complete.setSelected(false);complete.setVisible(false);busy(true);status.setText(I18n.text("Se compara local catalogul; fara API."));new SwingWorker<CatalogueStore.Preview,Void>(){protected CatalogueStore.Preview doInBackground()throws Exception{return store.preview(selected,file);}protected void done(){try{preview=get();details.setText(format(preview.data()));details.setCaretPosition(0);complete.setVisible(CatalogueStore.number(preview.data(),"absent_codes")>0);status.setText(I18n.text("Verifica diferentele si confirma fabrica inainte de activare."));}catch(Exception error){status.setText(message(error));}finally{busy(false);}}}.execute();}
 void activate(){if(running||preview==null||!apply.isEnabled())return;CatalogueStore.Preview selected=preview;boolean allowAbsent=complete.isSelected();busy(true);status.setText(I18n.text("Se importa catalogul; originalele se arhiveaza local."));new SwingWorker<Map<String,Object>,Void>(){protected Map<String,Object> doInBackground()throws Exception{return store.apply(selected,true,allowAbsent);}protected void done(){try{Map<String,Object> data=get();status.setText(I18n.text("Catalogul pentru {0} este activ. Sursa si versiunea precedenta sunt arhivate.",selected.factory()));details.append("\n\n"+I18n.text("Sursa arhivata: {0}",Objects.toString(Json.get(data,"source_archive"),"")));}catch(Exception error){status.setText(message(error));}finally{preview=null;confirmed.setSelected(false);complete.setSelected(false);busy(false);loadInfo();}}}.execute();}
 private static String date(Object value){if(value==null)return I18n.text("Data necunoscuta");try{return java.time.Instant.parse(value.toString()).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"));}catch(RuntimeException error){return value.toString();}}
 private void busy(boolean value){running=value;progress.setIndeterminate(value);controls();}
 private static String message(Exception error){Throwable cause=error.getCause();return Objects.toString(cause!=null?cause.getMessage():error.getMessage(),I18n.text("Catalog invalid."));}
 static String format(Map<String,Object> data){StringBuilder text=new StringBuilder(I18n.text("Total: {0}; articole MBS pentru import: {1}",CatalogueStore.number(data,"records"),CatalogueStore.number(data,"import_records")));text.append("\n").append(I18n.text("Noi: {0}; modificate: {1}; absente: {2}",CatalogueStore.number(data,"new_codes"),CatalogueStore.number(data,"changed_codes"),CatalogueStore.number(data,"absent_codes")));if(CatalogueStore.number(data,"import_records_without_units")>0)text.append("\n").append(I18n.text("Articole fara unitate explicita in catalog: {0}. Unitatile raman neconfirmate.",CatalogueStore.number(data,"import_records_without_units")));for(String key:List.of("new_articles","changed_codes","absent_articles")){Object rows=Json.get(data,"changes",key);if(rows instanceof List<?> list&&!list.isEmpty()){text.append("\n\n").append(I18n.text(key.equals("new_articles")?"Articole noi":key.equals("changed_codes")?"Articole modificate":"Articole absente")).append(":\n");for(Object row:list){text.append(Objects.toString(Json.get(row,"code"),"")).append('\n');if(key.equals("changed_codes")){text.append(I18n.text("Anterior")).append(":\n");entries(text,Json.get(row,"before"));text.append(I18n.text("Nou")).append(":\n");entries(text,Json.get(row,"after"));}else entries(text,Json.get(row,"entries"));}}}return text.toString();}
 private static void entries(StringBuilder text,Object raw){if(raw instanceof List<?> rows)for(Object row:rows){text.append("  ").append(Objects.toString(Json.get(row,"description"),""));Object fields=Json.get(row,"fields");if(fields instanceof Map<?,?> map)for(var item:map.entrySet())if(!Objects.toString(item.getValue(),"").isBlank())text.append(" | ").append(item.getKey()).append(": ").append(item.getValue());text.append('\n');}}
}
